int logfmt_parse_multi(const char *in, char **keys_out, char **vals_out, size_t max_pairs) {
    const char *start = in;
    size_t num_pairs = 0;

    while (*start && num_pairs < max_pairs) {
        const char *eq = strchr(start, '=');
        if (!eq) break;

        size_t klen = (size_t)(eq - start);
        keys_out[num_pairs] = malloc(klen + 1);
        if (!keys_out[num_pairs]) return -1;
        strncpy(keys_out[num_pairs], start, klen);
        keys_out[num_pairs][klen] = '\0';

        const char *quote = strchr(eq + 1, '"');
        if (quote) {
            size_t vlen = (size_t)(quote - (eq + 1));
            vals_out[num_pairs] = malloc(vlen + 1);
            if (!vals_out[num_pairs]) {
                for (size_t i = 0; i < num_pairs; ++i) free(keys_out[i]);
                return -1;
            }
            strncpy(vals_out[num_pairs], eq + 1, vlen);
            vals_out[num_pairs][vlen] = '\0';
            if (*(quote + 1) != '\0') {
                for (size_t i = 0; i <= num_pairs; ++i) free(keys_out[i]);
                return -1; // Invalid format, extra characters after closing quote
            }
        } else {
            const char *end = strchr(eq + 1, ' ');
            if (!end) end = strchr(eq + 1, '\0');
            size_t vlen = (size_t)(end - (eq + 1));
            vals_out[num_pairs] = malloc(vlen + 1);
            if (!vals_out[num_pairs]) {
                for (size_t i = 0; i <= num_pairs; ++i) free(keys_out[i]);
                return -1;
            }
            strncpy(vals_out[num_pairs], eq + 1, vlen);
            vals_out[num_pairs][vlen] = '\0';
        }

        start = end ? end + 1 : end;
        ++num_pairs;
    }

    return num_pairs;
}

