void logfmt_trim(char *s) {
    while (isspace((unsigned char)*s)) {
        ++s;
    }
    if (*s == '\0') return;

    char *e = s + strlen(s) - 1;
    while (e > s && isspace((unsigned char)*e)) {
        --e;
    }
    *(e + 1) = '\0';
}

